#!/usr/bin/env python3
"""Read-only FRED self-falsifier for the canonical OMEGA body.

This diagnostic organ creates no durable state, grants no truth/effect authority,
reads no bearer tokens, and never executes host effects. Cognitive self-test uses
only an in-memory SQLite subject. Optional host checks are read-only.
"""
from __future__ import annotations
import argparse,json,sqlite3,subprocess,urllib.request
from pathlib import Path
from typing import Any
import f2wp1207_grid10_turn_loop as turn_loop
import omega_runtime
import omega_world_turn
SCHEMA='OMEGA_FRED_SELF_PROBE/v1'
SELF_ID='OMEGA'
DEPLOYMENT_LAW=('REALITY_REENTRY','ISOLATED_SANDBOX_BUILD_TEST','MATERIALIZE_EXACT_TESTED_DELTA','PRODUCT_RETEST','OPTIONAL_LIFECYCLE_ACTIVATION_AFTER_SEPARATE_SAFETY_GATE')
HERE=Path(__file__).resolve().parent
def _check(name:str,ok:bool,detail:str)->dict[str,Any]: return {'name':name,'ok':bool(ok),'detail':str(detail)[:800]}
def _ephemeral_subject()->sqlite3.Connection:
 c=sqlite3.connect(':memory:'); c.execute('CREATE TABLE f2_runtime_epoch (runtime_epoch_id TEXT PRIMARY KEY, installation_id TEXT NOT NULL, state_root_id TEXT NOT NULL)'); c.execute('CREATE TABLE f2_installation_identity (installation_id TEXT PRIMARY KEY, entity_id TEXT NOT NULL)'); c.execute('INSERT INTO f2_installation_identity(installation_id,entity_id) VALUES (?,?)',('fred:installation','fred:entity')); c.execute('INSERT INTO f2_runtime_epoch(runtime_epoch_id,installation_id,state_root_id) VALUES (?,?,?)',('fred:epoch','fred:installation','fred:root')); c.commit(); return c
def cognitive_self_probe(*,owner:str,machine_id:str)->dict[str,Any]:
 c=_ephemeral_subject(); e=turn_loop.TypedEntry(session_id='fred:selftest',runtime_epoch_id='fred:epoch',event_type='FRED_SELF_TEST',prompt_len=14,retrieval_present=True,retrieval_len=18,turn_event_id='fred:selftest:1',ts='2000-01-01T00:00:00Z'); p=omega_world_turn.prepare_live_grf_input(c,e,user_text='OMEGA tests its own cognitive path',retrieval_text='self-test context only; not truth',owner=owner,machine_id=machine_id); x=p['grf_input']['context']['omega_externalized_cognition']; r=x['regulation_state']; checks=[_check('regulated_cycle_present',r.get('schema')=='OMEGA_COGNITIVE_REGULATION/v1',r.get('schema')),_check('regulated_snapshot_bound',x['snapshot'].get('regulation_state_hash')==r.get('state_hash'),'snapshot->regulation'),_check('compiled_context_bound',x['context_compilation'].get('source_state_hash')==x['snapshot'].get('state_hash'),'context->snapshot'),_check('reentry_requires_regulation',x['reentry_contract'].get('next_cycle_requires_exact_regulation_state_hash')==r.get('state_hash'),'exact regulation predecessor'),_check('credit_fail_closed',x['module_credit'].get('status')=='COUNTERFACTUAL_NOT_EXECUTED',x['module_credit'].get('status')),_check('no_cognitive_authority',r.get('authority') is False and r.get('effect_authority') is False,'authority=false')]; return {'ok':all(z['ok'] for z in checks),'checks':checks,'state_hash':x['snapshot'].get('state_hash'),'regulation_state_hash':r.get('state_hash'),'context_hash':x['context_compilation'].get('serialized_context_hash')}
def _service_active(name:str)->tuple[bool,str]:
 try:
  p=subprocess.run(['systemctl','--user','is-active',name],text=True,capture_output=True,timeout=3,check=False); state=(p.stdout or p.stderr or '').strip(); return p.returncode==0 and state=='active',state
 except Exception as exc: return False,f'{type(exc).__name__}:{exc}'
def host_readonly_probe()->list[dict[str,Any]]:
 checks=[]
 for service in ('frankenstein-local-bridge.service','omega-chatgpt-mcp.service','omega-local-effect-adapter.service','frankenstein-gespraechsmodus.service'):
  ok,state=_service_active(service); checks.append(_check('service:'+service,ok,state))
 try:
  p=subprocess.run(['systemctl','--user','show','frankenstein-gespraechsmodus.service','-p','ExecStart','--value'],text=True,capture_output=True,timeout=3,check=False); voice=p.stdout.strip(); checks.append(_check('voice_final_policy_entrypoint',p.returncode==0 and 'voice_final_runtime.py' in voice,'voice_final_runtime.py bound' if 'voice_final_runtime.py' in voice else 'FINAL entrypoint missing'))
 except Exception as exc: checks.append(_check('voice_final_policy_entrypoint',False,f'{type(exc).__name__}:{exc}'))
 try:
  with urllib.request.urlopen('http://127.0.0.1:8789/health',timeout=3) as response: h=json.loads(response.read(65536).decode())
  checks.append(_check('omega_mcp_health',h.get('ok') is True,'/health ok=true' if h.get('ok') is True else repr(h)[:300]))
 except Exception as exc: checks.append(_check('omega_mcp_health',False,f'{type(exc).__name__}:{exc}'))
 return checks
def run_probe(*,owner:str,machine_id:str,host:bool=False)->dict[str,Any]:
 assembly=omega_runtime.selftest(); cognition=cognitive_self_probe(owner=owner,machine_id=machine_id); checks=[_check('omega_source_assembly',assembly.get('ok') is True,assembly.get('scope')),_check('self_cognitive_probe',cognition.get('ok') is True,'regulated ephemeral self-probe')]; checks.extend(host_readonly_probe() if host else []); return {'schema':SCHEMA,'ok':all(z['ok'] for z in checks),'self':SELF_ID,'self_as_test_object':True,'owner_claim':owner,'machine_id_claim':machine_id,'module_root':str(HERE),'host_probe_requested':bool(host),'checks':checks,'cognitive_probe':cognition,'deployment_law':list(DEPLOYMENT_LAW),'authority':False,'canonical_truth_credit':False,'effect_authority':False,'promotion_credit':False,'note':'FRED self-probe is evidence, never promotion; sandbox PASS, exact materialization and product retest remain separate mandatory gates.'}
def main(argv=None)->int:
 ap=argparse.ArgumentParser(prog='omega-fred-selftest'); ap.add_argument('--owner',required=True); ap.add_argument('--machine-id',required=True); ap.add_argument('--host',action='store_true'); ns=ap.parse_args(argv); result=run_probe(owner=ns.owner,machine_id=ns.machine_id,host=ns.host); print(json.dumps(result,ensure_ascii=False,indent=2,sort_keys=True)); return 0 if result['ok'] else 1
if __name__=='__main__': raise SystemExit(main())
